package com.loadoutstudio;
import com.google.gson.*;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.util.*;
import java.util.zip.GZIPOutputStream;
import javax.swing.*;
import org.junit.Test;
import net.runelite.http.api.RuneLiteAPI;
import static org.junit.Assert.*;
public class ExportOptionsTest {
 private final SetupCodec codec=new SetupCodec(RuneLiteAPI.GSON);
 private static JsonObject setup(){JsonObject p=SetupCodec.blank("Boss – test");JsonObject item=SetupCodec.item(560,15000);item.addProperty("label","Death rune");JsonArray choices=new JsonArray();choices.add("Death rune");item.add("choices",choices);SetupCodec.setup(p).getAsJsonArray("inv").set(3,item);SetupCodec.setup(p).addProperty("notes","Unicode café 🎣\nKeep this note.");SetupCodec.rebuildLayout(p);return p;}
 private static void rejected(Runnable r){try{r.run();fail("Invalid export text accepted");}catch(IllegalArgumentException expected){assertNotNull(expected.getMessage());}}
 private static String gzip(byte[] data)throws Exception{ByteArrayOutputStream out=new ByteArrayOutputStream();try(GZIPOutputStream g=new GZIPOutputStream(out)){g.write(data);}return SetupExportText.PREFIX+Base64.getEncoder().encodeToString(out.toByteArray());}
 @Test public void prettyInventoryChangesOnlyWhitespaceAndKeepsPlainPluginJson(){JsonObject p=setup();String normal=codec.inventory(p),pretty=codec.inventory(p,true);assertFalse(normal.contains("\n"));assertTrue(pretty.contains("\n"));assertEquals(codec.parse(normal),codec.parse(pretty));assertFalse(codec.parse(pretty).getAsJsonObject().has("loadoutStudio"));assertEquals(1,codec.importText(pretty).size());assertEquals(p,setup());}
 @Test public void compressedNativeRoundTripRetainsLabelsChoicesUnicodeAndLayout(){JsonObject p=setup();String compressed=codec.studio(p,true,true);assertTrue(compressed.startsWith(SetupExportText.PREFIX));assertFalse(compressed.contains("\n"));JsonObject restored=codec.importText(compressed).get(0);assertEquals(1,restored.remove("loadoutStudio").getAsInt());assertEquals(p,restored);assertEquals(codec.studio(p,false,true),compressed);}
 @Test public void nativePrettyMarkerDoesNotLeakIntoInventoryExports(){String pretty=codec.studio(setup(),true,false);assertTrue(pretty.contains("\n"));JsonObject p=codec.importText(pretty).get(0);assertEquals(1,p.get("loadoutStudio").getAsInt());JsonObject external=codec.parse(codec.inventory(p,true)).getAsJsonObject();assertFalse(external.has("loadoutStudio"));assertFalse(SetupCodec.setup(external).getAsJsonArray("inv").get(3).getAsJsonObject().has("choices"));}
 @Test public void brokenBase64GzipTruncationAndVersionsAreRejected(){rejected(()->codec.importText("loadoutstudio:gz2:abc"));rejected(()->codec.importText(SetupExportText.PREFIX+"%%%"));rejected(()->codec.importText(SetupExportText.PREFIX+"e30="));String text=codec.studio(setup(),false,true);rejected(()->codec.importText(text.substring(0,text.length()-12)));JsonObject future=setup();future.addProperty("loadoutStudio",2);rejected(()->codec.importText(RuneLiteAPI.GSON.toJson(future)));future.addProperty("loadoutStudio","1");rejected(()->codec.importText(RuneLiteAPI.GSON.toJson(future)));}
 @Test public void compressedInputStillPassesExistingSchemaAndDepthChecks(){JsonObject bad=setup();SetupCodec.setup(bad).addProperty("fb","true");rejected(()->codec.importText(SetupExportText.compress(RuneLiteAPI.GSON.toJson(bad))));rejected(()->codec.importText(SetupExportText.compress("[".repeat(49)+"]".repeat(49))));}
 @Test public void expandedLimitAndInvalidUtf8AreRejected()throws Exception{String bomb=gzip(new byte[SetupCodec.MAX_TEXT+1]);rejected(()->codec.importText(bomb));String invalid=gzip(new byte[]{(byte)0xC3,0x28});rejected(()->codec.importText(invalid));rejected(()->SetupExportText.unpack(" ".repeat(SetupCodec.MAX_TEXT+1)));}
 private static class Host extends PanelTest.FakeHost {String copied;@Override public void copyText(String text){copied=text;}}
 private static JCheckBox check(StudioPanel p,String name){return (JCheckBox)OwnedGearPanelTest.find(p,name);}private static JComboBox<?> format(StudioPanel p){return (JComboBox<?>)OwnedGearPanelTest.find(p,"exportFormat");}private static String output(StudioPanel p){return ((JTextArea)OwnedGearPanelTest.find(p,"exportCode")).getText();}private static void click(StudioPanel p,String name){OwnedGearPanelTest.click(p,name);}
 @Test public void inventoryAndNativeCopyUseExactlyTheVisibleSelectedFormatting()throws Exception{SwingUtilities.invokeAndWait(()->{Host h=new Host();StudioPanel p=new StudioPanel(h,RuneLiteAPI.GSON);p.open(new SetupLibrary.Entry(setup()));click(p,"nav:Export");JCheckBox compress=check(p,"exportCompress"),pretty=check(p,"exportPrettyPrint");assertFalse(compress.isEnabled());assertTrue(pretty.isEnabled());pretty.doClick();assertTrue(output(p).contains("\n"));click(p,"Copy code");assertEquals(output(p),h.copied);assertFalse(h.copied.startsWith(SetupExportText.PREFIX));format(p).setSelectedIndex(3);assertTrue(compress.isEnabled());compress.doClick();assertFalse(pretty.isEnabled());assertTrue(output(p).startsWith(SetupExportText.PREFIX));click(p,"Copy code");assertEquals(output(p),h.copied);assertEquals("Boss – test",SetupCodec.name(codec.importText(h.copied).get(0)));compress.doClick();assertTrue(pretty.isEnabled());assertTrue(output(p).contains("\n"));p.dispose();});}
 @Test public void bankFormatsIgnoreRememberedJsonOptionsAndCopyNativeTagText()throws Exception{SwingUtilities.invokeAndWait(()->{Host h=new Host();StudioPanel p=new StudioPanel(h,RuneLiteAPI.GSON);JsonObject data=setup();p.open(new SetupLibrary.Entry(data));click(p,"nav:Export");format(p).setSelectedIndex(3);check(p,"exportCompress").doClick();for(int i:new int[]{1,2}){format(p).setSelectedIndex(i);assertFalse(check(p,"exportCompress").isEnabled());assertFalse(check(p,"exportPrettyPrint").isEnabled());click(p,"Copy code");assertEquals(codec.bank(data,i==2),h.copied);assertEquals(output(p),h.copied);}format(p).setSelectedIndex(0);assertTrue(check(p,"exportPrettyPrint").isEnabled());assertFalse(output(p).startsWith(SetupExportText.PREFIX));p.dispose();});}
 @Test public void optionsFitNarrowSidebarAndDefaultExternalOutputIsUnchanged()throws Exception{SwingUtilities.invokeAndWait(()->{for(int width:new int[]{220,260}){Host h=new Host();StudioPanel p=new StudioPanel(h,RuneLiteAPI.GSON);p.open(new SetupLibrary.Entry(setup()));p.setSize(width,900);click(p,"nav:Export");click(p,"Show code");OwnedGearPanelTest.layout(p);OwnedGearPanelTest.layout(p);assertEquals(codec.inventory(setup()),output(p));for(String name:new String[]{"exportCompress","exportPrettyPrint"}){JCheckBox b=check(p,name);assertTrue(b.getWidth()>65);assertTrue(b.getX()+b.getWidth()<=b.getParent().getWidth());}p.dispose();}});}
}
